window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-32fa28a1e914dd0c"]={"versions": [{"id": "FIG-32fa28a1e914dd0c", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Architektur- und Komponentendiagramm (AUTOSAR Component &amp; Connector View, VFB-Sicht).\n</li><li><strong>Funktionale Einordnung:</strong> Repräsentiert die Phase <em>Development of the Overall VFB System</em> ([TR_METH_01045], Upstream: <code>RS_METH_00006</code>, <code>RS_METH_00033</code>).\n</li><li><strong>Technischer Zweck:</strong> Vollständige Abstraktion der Software-Kommunikation von physischer Hardware, Steuergeräte-Topologie (<code>EcuInstance</code>) und Bus-Netzwerken. Es bildet die oberste logische Spezifikationsebene vor dem System-Mapping und der Signal-/PDU-Allokation ([TR_METH_01046]).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Components (SW-C 1 bis SW-C 4):</strong>\n<ul class=\"fig-list\"><li>Metamodell-Klassifikation: <code>SwComponentPrototype</code> innerhalb einer übergeordneten <code>CompositionSwComponentType</code>, typisiert über atomare Software-Komponenten (<code>AtomicSwComponentType</code>, z. B. <code>ApplicationSwComponentType</code>).\n</li></ul>\n</li><li><strong>Ports (Quadrate an den Komponentengrenzen):</strong>\n<ul class=\"fig-list\"><li><code>PortPrototype</code>: Spezifiziert als <code>PPortPrototype</code> (Provide), <code>RPortPrototype</code> (Require) oder <code>PRPortPrototype</code>.\n</li><li>Typisierung über <code>PortInterface</code> (z. B. <code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>NvDataInterface</code>).\n</li></ul>\n</li><li><strong>Verbindungs- und Bus-Entitäten (Virtual Functional Bus):</strong>\n<ul class=\"fig-list\"><li>Der VFB kapselt die logischen Verbindungen (<code>AssemblySwConnector</code>), dargestellt durch gestrichelte Linien:\n<ul class=\"fig-list\"><li><code>SW-C 1</code> (Port 1) ↔ <code>SW-C 3</code> (Port 1)\n</li><li><code>SW-C 1</code> (Port 2) ↔ <code>SW-C 2</code> (Port 1)\n</li><li><code>SW-C 2</code> (Port 2) ↔ <code>SW-C 4</code> (Port 1)\n</li><li><code>SW-C 3</code> (Port 2) ↔ <code>SW-C 4</code> (Port 2)\n</li></ul>\n</li><li>Kardinalität: Im Diagramm als 1:1-Verbindungen dargestellt (im Metamodell sind für Sender-Receiver auch 1:n- und n:1-Topologien zulässig).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ablaufeigenschaften:</strong> Statisches Strukturdiagramm ohne expliziten Zeitablauf.\n</li><li><strong>VFB-Interaktionssemantik (zur Laufzeit):</strong>\n<ul class=\"fig-list\"><li><strong>Sender-Receiver-Kommunikation:</strong> Asynchroner Datenaustausch via Queueing (<code>last-is-best</code> oder FIFO) getriggert über <code>DataReceivedEvent</code> oder <code>DataReceiveErrorEvent</code>.\n</li><li><strong>Client-Server-Kommunikation:</strong> Request-Response-Muster. Synchrone Aufrufe (Aufrufer blockiert) oder asynchrone Aufrufe (<code>Rte_Call</code> mit nachgelagertem <code>Rte_Result</code> bzw. Callback-Aktivierung via <code>AsynchronousServerCallReturnsEvent</code>).\n</li><li><strong>Fehlerpfade:</strong> Übertragung von Application Errors (Client-Server) oder Status-Rückgabewerten (<code>RTE_E_OK</code>, <code>RTE_E_LOST_DATA</code>, <code>RTE_E_TIMEOUT</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Ortstransparenz (Location Transparency):</strong> \n<ul class=\"fig-list\"><li>SW-C-Implementierer programmieren ausschließlich gegen die abstrakte RTE-API (<code>Rte_Read_&lt;p&gt;_&lt;d&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;d&gt;</code>, <code>Rte_Call_&lt;p&gt;_&lt;o&gt;</code>).\n</li><li>Für den C-Code einer SW-C ist irrelevant, ob der Kommunikationspartner auf demselben Core, einem anderen Core (Multicore-RTE), auf derselben ECU oder über Busgrenzen hinweg (CAN/LIN/FlexRay/Ethernet via BSW COM-Stack) liegt.\n</li></ul>\n</li><li><strong>RTE Contract vs. Generation Phase:</strong>\n<ul class=\"fig-list\"><li>Im VFB-Designstadium wird der Komponenten-Header (<code>Rte_&lt;swc&gt;.h</code>) in der <em>Contract Phase</em> generiert.\n</li><li>Erst nach dem <em>ECU Mapping</em> und der <em>Communication Matrix Definition</em> bindet der RTE-Generator in der <em>Generation Phase</em> die VFB-Kanäle entweder an lokale Speicherbereiche/OS-Events (Intra-ECU) oder an den AUTOSAR COM-Stack bzw. Transformer (Inter-ECU, z. B. SOME/IP, E2E-Protection).\n</li></ul>\n</li><li><strong>Restriktionen:</strong> Direkte Zugriffe von SW-Cs auf Treiber, Controller-Register oder OS-Primitiven sind im VFB-Konzept strikt untersagt; alle Interaktionen müssen über typisierte Ports laufen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-212d9cdc0e30a4df", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Architektur- und Komponentendiagramm (AUTOSAR Component &amp; Connector View, VFB-Sicht).\n</li><li><strong>Funktionale Einordnung:</strong> Repräsentiert die Phase <em>Development of the Overall VFB System</em> ([TR_METH_01045], Upstream: <code>RS_METH_00006</code>, <code>RS_METH_00033</code>).\n</li><li><strong>Technischer Zweck:</strong> Vollständige Abstraktion der Software-Kommunikation von physischer Hardware, Steuergeräte-Topologie (<code>EcuInstance</code>) und Bus-Netzwerken. Es bildet die oberste logische Spezifikationsebene vor dem System-Mapping und der Signal-/PDU-Allokation ([TR_METH_01046]).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Components (SW-C 1 bis SW-C 4):</strong>\n<ul class=\"fig-list\"><li>Metamodell-Klassifikation: <code>SwComponentPrototype</code> innerhalb einer übergeordneten <code>CompositionSwComponentType</code>, typisiert über atomare Software-Komponenten (<code>AtomicSwComponentType</code>, z. B. <code>ApplicationSwComponentType</code>).\n</li></ul>\n</li><li><strong>Ports (Quadrate an den Komponentengrenzen):</strong>\n<ul class=\"fig-list\"><li><code>PortPrototype</code>: Spezifiziert als <code>PPortPrototype</code> (Provide), <code>RPortPrototype</code> (Require) oder <code>PRPortPrototype</code>.\n</li><li>Typisierung über <code>PortInterface</code> (z. B. <code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>NvDataInterface</code>).\n</li></ul>\n</li><li><strong>Verbindungs- und Bus-Entitäten (Virtual Functional Bus):</strong>\n<ul class=\"fig-list\"><li>Der VFB kapselt die logischen Verbindungen (<code>AssemblySwConnector</code>), dargestellt durch gestrichelte Linien:\n<ul class=\"fig-list\"><li><code>SW-C 1</code> (Port 1) ↔ <code>SW-C 3</code> (Port 1)\n</li><li><code>SW-C 1</code> (Port 2) ↔ <code>SW-C 2</code> (Port 1)\n</li><li><code>SW-C 2</code> (Port 2) ↔ <code>SW-C 4</code> (Port 1)\n</li><li><code>SW-C 3</code> (Port 2) ↔ <code>SW-C 4</code> (Port 2)\n</li></ul>\n</li><li>Kardinalität: Im Diagramm als 1:1-Verbindungen dargestellt (im Metamodell sind für Sender-Receiver auch 1:n- und n:1-Topologien zulässig).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ablaufeigenschaften:</strong> Statisches Strukturdiagramm ohne expliziten Zeitablauf.\n</li><li><strong>VFB-Interaktionssemantik (zur Laufzeit):</strong>\n<ul class=\"fig-list\"><li><strong>Sender-Receiver-Kommunikation:</strong> Asynchroner Datenaustausch via Queueing (<code>last-is-best</code> oder FIFO) getriggert über <code>DataReceivedEvent</code> oder <code>DataReceiveErrorEvent</code>.\n</li><li><strong>Client-Server-Kommunikation:</strong> Request-Response-Muster. Synchrone Aufrufe (Aufrufer blockiert) oder asynchrone Aufrufe (<code>Rte_Call</code> mit nachgelagertem <code>Rte_Result</code> bzw. Callback-Aktivierung via <code>AsynchronousServerCallReturnsEvent</code>).\n</li><li><strong>Fehlerpfade:</strong> Übertragung von Application Errors (Client-Server) oder Status-Rückgabewerten (<code>RTE_E_OK</code>, <code>RTE_E_LOST_DATA</code>, <code>RTE_E_TIMEOUT</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Ortstransparenz (Location Transparency):</strong> \n<ul class=\"fig-list\"><li>SW-C-Implementierer programmieren ausschließlich gegen die abstrakte RTE-API (<code>Rte_Read_&lt;p&gt;_&lt;d&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;d&gt;</code>, <code>Rte_Call_&lt;p&gt;_&lt;o&gt;</code>).\n</li><li>Für den C-Code einer SW-C ist irrelevant, ob der Kommunikationspartner auf demselben Core, einem anderen Core (Multicore-RTE), auf derselben ECU oder über Busgrenzen hinweg (CAN/LIN/FlexRay/Ethernet via BSW COM-Stack) liegt.\n</li></ul>\n</li><li><strong>RTE Contract vs. Generation Phase:</strong>\n<ul class=\"fig-list\"><li>Im VFB-Designstadium wird der Komponenten-Header (<code>Rte_&lt;swc&gt;.h</code>) in der <em>Contract Phase</em> generiert.\n</li><li>Erst nach dem <em>ECU Mapping</em> und der <em>Communication Matrix Definition</em> bindet der RTE-Generator in der <em>Generation Phase</em> die VFB-Kanäle entweder an lokale Speicherbereiche/OS-Events (Intra-ECU) oder an den AUTOSAR COM-Stack bzw. Transformer (Inter-ECU, z. B. SOME/IP, E2E-Protection).\n</li></ul>\n</li><li><strong>Restriktionen:</strong> Direkte Zugriffe von SW-Cs auf Treiber, Controller-Register oder OS-Primitiven sind im VFB-Konzept strikt untersagt; alle Interaktionen müssen über typisierte Ports laufen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-32fa28a1e914dd0c", "to": "FIG-212d9cdc0e30a4df", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
